<script setup>
import { computed, ref } from 'vue';
import { Link, router, usePage } from '@inertiajs/vue3';
import axios from 'axios';
import AssessmentLayout from './AssessmentLayout.vue';
import { submissionContentToHtml } from '@/Utils/richText';

const props = defineProps({ submission: Object, rubric: Object, aiAdvisorConfig: Object });
const page = usePage();
const quest = computed(() => props.submission.quest || {});
const bank = computed(() => quest.value.task_bank || null);
const questions = computed(() => bank.value?.questions || []);
const answers = computed(() => props.submission.scores_detail?.answers || {});
const essayQuestions = computed(() => questions.value.filter(q => !['multiple_choice','platforming','word_match'].includes(q.question_type)));
const autoType = computed(() => ['multiple_choice','platforming','word_match'].includes(bank.value?.assessment_type));
const autoChecked = computed(() => props.submission.scores_detail?.source === 'task_bank_auto_check' && !essayQuestions.value.length);
const mode = computed(() => bank.value ? (autoChecked.value ? 'auto' : 'bank') : (props.rubric ? 'rubric' : 'manual'));
const modeLabel = computed(() => ({auto:'Dinilai otomatis oleh bank soal',bank:'Esai dan soal campuran',rubric:'Penilaian dengan rubrik',manual:'Penilaian manual'})[mode.value]);
const savedEssay = props.submission.scores_detail?.verdict?.task_bank?.essay?.by_question || {};
const questionPoints = ref(Object.fromEntries(essayQuestions.value.map(q => [q.uuid,Number(savedEssay[q.uuid]?.score_percent ?? 0)])));
const selectedLevels = ref({...(props.submission.scores_detail?.verdict?.selected_level_by_criteria_id || {})});
const finalScore = ref(Number(props.submission.grade ?? 0));
const status = ref(['Approved','Rejected'].includes(props.submission.status) ? props.submission.status : 'Approved');
const feedback = ref(props.submission.feedback || '');
const busy = ref(false), error = ref(''), aiOpen = ref(false), aiBusy = ref(false), aiError = ref(''), aiNotice = ref(''), aiStep = ref(''), aiProgress = ref(0);
const outputStage = ref('ai_evaluation_result'), selectedFile = ref(0);
const answerFor = q => answers.value[q.uuid] ?? '';
const parsed = q => { try { return JSON.parse(answerFor(q)); } catch { return null; } };
const optionText = o => typeof o === 'object' ? (o.text || o.label || o.value || 'Opsi gambar') : String(o);
const optionImage = o => { if(typeof o !== 'object') return null; if(o.image_url) return o.image_url; if(o.image_path) return `/storage/${String(o.image_path).replace(/^\/+/, '')}`; return null; };
const correct = q => String(answerFor(q)).trim() !== '' && String(answerFor(q)).trim() === String(q.answer_key || '').trim();
const gameResult = q => { const data=parsed(q), index=questions.value.filter(x=>x.question_type==='platforming').findIndex(x=>x.uuid===q.uuid); return data?.answers?.find(x=>Number(x.stage)===index) || data?.answers?.[index] || {}; };
const wordResult = q => { const data=parsed(q); return {data,blanks:(q.options_json?.blanks || []).map((expected,i)=>({expected,placed:data?.placed?.[i] || ''}))}; };
const scorePreview = computed(() => { if(autoChecked.value) return Number(props.submission.grade ?? 0); if(bank.value){const total=questions.value.reduce((n,q)=>n+Number(q.weight || 0),0),earned=questions.value.reduce((n,q)=>n+Number(q.weight || 0)*(q.question_type==='multiple_choice'?(correct(q)?1:0):Number(questionPoints.value[q.uuid] || 0)/100),0);return total?Math.round(earned/total*100):0;} if(props.rubric){const levels=props.rubric.levels || [],max=Math.max(0,...levels.map(l=>Number(l.score_value))),criteria=props.rubric.criteria || [],weight=criteria.reduce((n,c)=>n+Number(c.weight),0),earned=criteria.reduce((n,c)=>{const level=levels.find(l=>l.id===Number(selectedLevels.value[c.id]));return n+(max?Number(level?.score_value || 0)/max*Number(c.weight):0);},0);return weight?Math.round(earned/weight*100):0;} return Number(finalScore.value || 0); });
const saveVerdict = () => { error.value=''; if(mode.value==='rubric' && (props.rubric.criteria || []).some(c=>!selectedLevels.value[c.id])){error.value='Pilih level untuk semua kriteria.';return;} const payload={status:status.value,feedback:feedback.value}; if(bank.value)payload.question_points=questionPoints.value;else if(props.rubric)payload.selected_levels=selectedLevels.value;else payload.final_score=Number(finalScore.value);busy.value=true;router.post(route('admin.submissions.verdict',props.submission.uuid),payload,{preserveScroll:true,onFinish:()=>busy.value=false}); };
const files = computed(() => {const list=[...(props.submission.attachments || [])];if(props.submission.file_path && !list.some(f=>f.file_path===props.submission.file_path))list.unshift({id:null,file_path:props.submission.file_path,original_name:props.submission.file_path.split('/').pop()});return list;});
const fileUrl = f => route('admin.submissions.file',{submission:props.submission.uuid,...(f.id?{attachment:f.id}:{})});
const ext = f => (f?.original_name || f?.file_path || '').split('.').pop().toLowerCase();
const stages = [ ['extraction_result','Ekstrak bukti','admin.submissions.startPreprocessing'],['cleaning_result','Bersihkan teks','admin.submissions.startCleaning'],['structure_result','Baca struktur','admin.submissions.startStructureDetection'],['semantic_result','Pahami konteks','admin.submissions.startSemanticEnrichment'],['rubric_preparation_result','Siapkan kriteria','admin.submissions.startRubricPreparation'],['ai_evaluation_result','Saran AI','admin.submissions.startAiEvaluation'],['post_evaluation_validation_result','Validasi saran','admin.submissions.startPostEvaluationValidation'],['result_presentation_result','Ringkas hasil','admin.submissions.startResultPresentation'] ];
const pipelineComplete = computed(() => props.submission.pipeline_status === 'evaluated' && ['success','partial'].includes(props.submission.result_presentation_result?.result_presentation_status));
const lastStageResult = ref(null);
const normalizeScores = items => (Array.isArray(items) ? items : []).map((item,index) => ({question_number:Number(item?.question_number || 0) || index+1,score:Number(item?.mentor_view?.final_score ?? item?.normalized_score ?? item?.final_score ?? item?.score ?? item?.criteria_validation?.total_criteria_score)})).filter(item=>Number.isFinite(item.score));
const applyPipelineScores = result => { if(!essayQuestions.value.length)return 0;const sources=[result?.items,props.submission.result_presentation_items,props.submission.post_evaluation_validation_items,props.submission.ai_evaluation_items];const entries=normalizeScores(sources.find(items=>Array.isArray(items) && items.length) || []);if(!entries.length)return 0;let count=0;essayQuestions.value.forEach(q=>{const index=questions.value.findIndex(item=>item.uuid===q.uuid),match=entries.find(item=>item.question_number===index+1) || entries[index] || (entries.length===1?entries[0]:null);if(!match)return;questionPoints.value[q.uuid]=Math.max(0,Math.min(100,Math.round(match.score)));count++;});return count;};
const applyAdvisor = data => {const confidence=Number(data?.confidence?.overall || 0)-(data?.is_fallback?10:0),threshold=Number(props.aiAdvisorConfig?.auto_apply_min_confidence ?? 65),feedbackItems=Array.isArray(data?.question_feedback)?data.question_feedback:[],complete=!bank.value || questions.value.every(q=>feedbackItems.some(item=>String(item.question_uuid || item.uuid)===String(q.uuid))),allow=confidence>=threshold && complete;let filled=0;
  if(!bank.value && !props.rubric){const range=String(data.suggested_score_range || '').match(/^(\d{1,3})\s*-\s*(\d{1,3})$/),suggested=range?Math.round((Number(range[1])+Number(range[2]))/2):Math.round((Number(data.func || 0)+Number(data.logic || 0)+Number(data.clean || 0))/3);if(Number.isFinite(suggested)){finalScore.value=Math.max(0,Math.min(100,suggested));filled++;}}
  if(allow && props.rubric){const levels=props.rubric.levels || [];for(const item of data.rubric_recommendations || []){const criterion=(props.rubric.criteria || []).find(c=>Number(c.id)===Number(item.criteria_id) || String(c.name).toLowerCase()===String(item.criteria_name || '').toLowerCase());const level=levels.find(l=>Number(l.id)===Number(item.suggested_level_id) || Number(l.level)===Number(item.suggested_level || item.level) || String(l.label).toLowerCase()===String(item.suggested_level_label || item.level_label || '').toLowerCase());if(criterion && level){selectedLevels.value[criterion.id]=level.id;filled++;}}if(!filled && levels.length){const range=String(data.suggested_score_range || '').match(/^(\d{1,3})\s*-\s*(\d{1,3})$/),target=range?(Number(range[1])+Number(range[2]))/2:Number(data.func || 0),max=Math.max(...levels.map(l=>Number(l.score_value || 0)));if(target>0 && max>0){const nearest=[...levels].sort((a,b)=>Math.abs(Number(a.score_value)/max*100-target)-Math.abs(Number(b.score_value)/max*100-target))[0];for(const criterion of props.rubric.criteria || []){selectedLevels.value[criterion.id]=nearest.id;filled++;}}}}
  if(allow && essayQuestions.value.length){for(const item of data.essay_scores || []){const q=essayQuestions.value.find(x=>String(x.uuid)===String(item.question_uuid || item.uuid));if(!q)continue;const max=Number(item.max_score ?? q.weight),raw=Number(item.score ?? item.score_awarded);if(!Number.isFinite(raw))continue;questionPoints.value[q.uuid]=Math.max(0,Math.min(100,Math.round(max>0 && raw<=max ? raw/max*100 : raw)));filled++;}}
  const suggestion=[data.summary,data.suggested_feedback || data.feedback].filter(Boolean).join(' · ');if(suggestion){feedback.value=`[Saran AI] ${suggestion}${feedback.value ? `\n\n${feedback.value}` : ''}`;filled++;}return {filled,allow,confidence};};
const fetchAdvisor = async () => {try{const {data}=await axios.post(route('admin.submissions.checkAI',props.submission.uuid),{advisor_note:''});return applyAdvisor(data);}catch(e){aiError.value=`Tahapan selesai, tetapi saran AI untuk form belum tersedia: ${e.response?.data?.message || 'periksa hasil teknis'}.`;return {filled:0,allow:false};}};
const runStage = async stage => {aiBusy.value=true;aiError.value='';aiNotice.value='';aiStep.value=stage[1];outputStage.value=stage[0];try{const {data}=await axios.post(route(stage[2],props.submission.uuid));if(stage[0]==='result_presentation_result')applyPipelineScores(data);aiNotice.value=`${stage[1]} selesai. Tinjau hasilnya sebelum memberi nilai.`;router.reload({preserveScroll:true});}catch(e){aiError.value=e.response?.data?.message || `${stage[1]} gagal. Periksa tahap sebelumnya.`;router.reload({preserveScroll:true});}finally{aiBusy.value=false;aiStep.value='';}};
const runAll = async () => {if(aiBusy.value)return;aiBusy.value=true;aiError.value='';aiNotice.value='';aiProgress.value=0;try{let result=null;for(let i=0;i<stages.length;i++){const stage=stages[i];aiStep.value=stage[1];outputStage.value=stage[0];const response=await axios.post(route(stage[2],props.submission.uuid));result=response.data;aiProgress.value=Math.round((i+1)/stages.length*100);}lastStageResult.value=result;const pipelineFilled=applyPipelineScores(result);aiStep.value='Mengisi saran ke form';const advisor=await fetchAdvisor();aiNotice.value=`Delapan tahap selesai. ${pipelineFilled+advisor.filled} isian penilaian diperbarui; periksa sebelum menyimpan.`;router.reload({preserveScroll:true});}catch(e){aiError.value=e.response?.data?.message || `Proses berhenti pada ${aiStep.value}.`;router.reload({preserveScroll:true});}finally{aiBusy.value=false;aiStep.value='';}};
const rerun = async () => {if(aiBusy.value)return;aiBusy.value=true;aiError.value='';aiNotice.value='';aiStep.value='Periksa ulang hasil AI';try{await axios.post(route('admin.submissions.rerunAiEvaluation',props.submission.uuid));const advisor=await fetchAdvisor();aiNotice.value=`Pemeriksaan ulang selesai. ${advisor.filled} isian diperbarui; periksa sebelum menyimpan.`;router.reload({preserveScroll:true,onSuccess:()=>applyPipelineScores({items:props.submission.result_presentation_items})});}catch(e){aiError.value=e.response?.data?.message || 'Pemeriksaan ulang gagal.';router.reload({preserveScroll:true});}finally{aiBusy.value=false;aiStep.value='';}};
const output = computed(() => props.submission[outputStage.value]);
const stageState = stage => { const result=props.submission[stage[0]];if(!result)return 'Belum dijalankan';const status=Object.entries(result).find(([key])=>key.endsWith('_status'))?.[1];return status==='success'?'Berhasil':status==='partial'?'Parsial':status==='failed'?'Gagal':'Ada hasil'; };
const outputItems = computed(() => Array.isArray(output.value?.items) ? output.value.items : []);
const outputWarnings = computed(() => Array.isArray(output.value?.warnings) ? output.value.warnings : []);
const outputStatus = computed(() => output.value && Object.entries(output.value).find(([key])=>key.endsWith('_status'))?.[1]);
const readableAnswer = value => String(value || '').replace(/\r?\n/g, ' ').replace(/[ \t]+/g, ' ').trim();
</script>

<template>
<AssessmentLayout title="Periksa submission" :subtitle="`${submission.user?.name || 'Peserta'} · ${quest.title || 'Quest'} · Percobaan ${submission.attempt_number || 1}`">
<template #action><Link class="secondary" :href="route('redesign.quests.submissions',quest.uuid)">Kembali ke daftar</Link></template>
<div class="inspect-summary"><div><small>Metode penilaian</small><strong>{{ modeLabel }}</strong></div><div><small>Status</small><strong>{{ submission.status }}</strong></div><div><small>Nilai tersimpan</small><strong>{{ submission.grade ?? 'Belum dinilai' }}</strong></div><div v-if="bank"><small>Task bank</small><strong>{{ bank.name }} · {{ bank.assessment_type }}</strong></div></div>
<div class="inspect-grid"><section class="panel evidence"><h2>Jawaban dan bukti peserta</h2><p class="muted">Periksa jawaban asli sebelum menyimpan keputusan.</p><div v-if="quest.description" class="objective"><strong>Instruksi quest</strong><p>{{ quest.description.replace(/<[^>]*>/g,' ').trim() }}</p></div><div v-if="submission.content" class="answer-text submission-rich-text" v-html="submissionContentToHtml(submission.content)"></div><p v-if="submission.link"><a :href="submission.link" target="_blank" rel="noopener noreferrer">Buka tautan jawaban ↗</a></p>
<article v-for="(q,i) in questions" :key="q.uuid" class="question"><div class="question-head"><span>Soal {{ i+1 }} · {{ q.question_type?.replaceAll('_',' ') }}</span><span>Bobot {{ q.weight || 0 }}</span></div><h3>{{ q.question_text }}</h3>
<template v-if="q.question_type==='multiple_choice'"><p>Jawaban: <strong>{{ answerFor(q) || 'Tidak dijawab' }}</strong></p><div v-if="Array.isArray(q.options_json)" class="options"><div v-for="(option,oi) in q.options_json" :key="oi" :class="{chosen:optionText(option)===String(answerFor(q)),correct:optionText(option)===String(q.answer_key)}"><img v-if="optionImage(option)" :src="optionImage(option)" alt="" />{{ optionText(option) }}</div></div><p>Kunci: <strong>{{ q.answer_key || '—' }}</strong> · {{ correct(q) ? 'Benar' : 'Belum benar' }}</p></template>
<template v-else-if="q.question_type==='platforming'"><p>Jawaban stage: <strong>{{ gameResult(q).answer || 'Tidak dijawab' }}</strong></p><p class="muted">Kunci: {{ q.options_json?.stages?.[0]?.correct_answer || '—' }} · {{ gameResult(q).correct ? 'Benar' : 'Belum benar' }}</p></template>
<template v-else-if="q.question_type==='word_match'"><p class="muted">{{ wordResult(q).data?.complete ? 'Selesai' : 'Belum selesai' }} · {{ wordResult(q).data?.correct_count ?? 0 }}/{{ wordResult(q).data?.total ?? wordResult(q).blanks.length }} cocok</p><div class="options"><div v-for="(blank,bi) in wordResult(q).blanks" :key="bi" :class="{correct:blank.placed===blank.expected}">{{ blank.placed || 'Kosong' }} → {{ blank.expected }}</div></div></template>
<template v-else><div class="answer-text answer-box">{{ answerFor(q) || 'Tidak dijawab' }}</div><label v-if="bank" class="inline-essay-score" :for="`essay-score-${q.uuid}`"><span>Nilai jawaban esai <small>Bobot {{ q.weight || 0 }} · 0–100</small></span><input :id="`essay-score-${q.uuid}`" v-model.number="questionPoints[q.uuid]" form="submission-verdict" type="number" min="0" max="100" required /></label></template></article>
<div v-if="files.length" class="file-viewer"><h3>Berkas submission</h3><div class="file-tabs"><button v-for="(file,i) in files" :key="file.id || file.file_path" type="button" :class="{selected:selectedFile===i}" @click="selectedFile=i">{{ file.original_name || `File ${i+1}` }}</button></div><div class="file-body"><img v-if="['png','jpg','jpeg','gif','webp','svg'].includes(ext(files[selectedFile]))" :src="fileUrl(files[selectedFile])" :alt="files[selectedFile].original_name" /><iframe v-else-if="ext(files[selectedFile])==='pdf'" :src="fileUrl(files[selectedFile])" title="Pratinjau PDF submission" /><p v-else class="muted">Pratinjau tidak tersedia untuk format ini.</p></div><a :href="fileUrl(files[selectedFile])" target="_blank" rel="noopener">Buka atau unduh file ↗</a></div><p v-if="!submission.content && !questions.length && !files.length && !submission.link" class="muted">Belum ada jawaban atau berkas.</p></section>
<aside><form id="submission-verdict" class="panel decision" @submit.prevent="saveVerdict"><h2>Keputusan penilaian</h2><p class="muted">Nilai akhir dan reward dihitung sistem saat disimpan.</p><p v-if="autoChecked" class="note">Bank soal ini sudah dinilai otomatis: {{ submission.grade ?? 0 }}/100.</p><p v-else-if="bank && essayQuestions.length" class="note">Isi nilai esai tepat di bawah jawaban masing-masing soal.</p><p v-else-if="bank" class="muted">Periksa hasil otomatis di sebelah kiri sebelum menyimpan.</p><template v-else-if="rubric"><p class="note">Rubrik: {{ rubric.rubric?.title }}</p><label v-for="c in rubric.criteria || []" :key="c.id">{{ c.name }} · bobot {{ c.weight }}<select v-model="selectedLevels[c.id]" required><option value="">Pilih level</option><option v-for="l in rubric.levels || []" :key="l.id" :value="l.id">{{ l.label }} ({{ l.score_value }})</option></select><small v-if="selectedLevels[c.id]">{{ rubric.matrix?.[c.id]?.[selectedLevels[c.id]] || '' }}</small></label></template><label v-else>Nilai akhir 0–100<input v-model.number="finalScore" type="number" min="0" max="100" required /></label><div class="score-preview"><span>Perkiraan nilai</span><strong>{{ scorePreview }}/100</strong></div><label>Keputusan<select v-model="status"><option value="Approved">Setujui</option><option value="Rejected">Tolak</option></select></label><label>Umpan balik<textarea v-model="feedback" rows="5" placeholder="Alasan dan saran untuk peserta" /></label><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="Object.keys(page.props.errors || {}).length" class="error" role="alert">{{ Object.values(page.props.errors).join(' · ') }}</p><p v-if="page.props.flash?.message" class="success" role="status">{{ page.props.flash.message }}</p><button class="primary" :disabled="busy">{{ busy ? 'Menyimpan...' : 'Simpan keputusan' }}</button><Link v-if="page.props.auth?.user?.role !== 'mentor'" :href="route('redesign.submissions.edit',submission.uuid)">Edit data submission</Link></form></aside></div>
<section v-if="!autoType" class="panel ai-section">
  <div class="ai-head"><div><h2>Bantuan pemeriksaan AI <span>Opsional</span></h2><p class="muted">Delapan tahap membantu membaca bukti dan menyiapkan saran. Nilai serta keputusan akhir tetap diperiksa penilai.</p></div><button type="button" class="secondary" :aria-expanded="aiOpen" @click="aiOpen=!aiOpen">{{ aiOpen ? 'Sembunyikan' : 'Buka bantuan AI' }}</button></div>
  <div v-if="aiOpen" class="ai-content">
    <div class="ai-actions"><button type="button" class="primary" :disabled="aiBusy" @click="pipelineComplete ? rerun() : runAll()">{{ aiBusy ? `Memproses ${aiStep}...` : pipelineComplete ? 'Periksa ulang' : 'Jalankan bantuan AI' }}</button><span class="muted">Status: {{ submission.pipeline_status?.replaceAll('_',' ') || 'Belum dimulai' }}</span></div>
    <p v-if="aiBusy" class="muted" role="status">Tahap berjalan: {{ aiStep }} · {{ aiProgress }}%</p>
    <p v-if="aiError" class="error" role="alert">{{ aiError }}</p><p v-if="aiNotice" class="success" role="status">{{ aiNotice }}</p>
    <details><summary>Lihat tahapan dan hasil teknis</summary>
      <div class="stages"><button v-for="(s,i) in stages" :key="s[0]" type="button" :disabled="aiBusy" @click="runStage(s)">{{ i+1 }}. {{ s[1] }} <small>{{ stageState(s) }}</small></button></div>
      <div class="file-tabs"><button v-for="s in stages" :key="s[0]" type="button" :class="{selected:outputStage===s[0]}" @click="outputStage=s[0]">{{ s[1] }}</button></div>
      <div v-if="output" class="stage-output"><div class="stage-meta"><strong>{{ stages.find(s=>s[0]===outputStage)?.[1] }}</strong><span>Status: {{ outputStatus || '—' }}</span></div><p v-if="outputWarnings.length" class="error">Peringatan: {{ outputWarnings.join(' · ') }}</p>
        <template v-if="outputStage==='extraction_result'"><p class="muted">{{ output.detected_content_type || 'Tipe tidak diketahui' }} · {{ output.extraction_method || 'Metode tidak diketahui' }} · {{ output.page_count ?? 0 }} halaman</p><pre>{{ output.raw_text || 'Tidak ada teks yang berhasil diekstrak.' }}</pre></template>
        <template v-else-if="outputStage==='cleaning_result'"><p class="muted">Bahasa: {{ output.language || '—' }} · Noise: {{ output.changes_summary?.noise_removed ?? 0 }} · OCR: {{ output.changes_summary?.ocr_corrections ?? 0 }} · Baris: {{ output.changes_summary?.line_break_fixed ?? 0 }}</p><pre>{{ output.clean_text || 'Belum ada teks bersih.' }}</pre></template>
        <template v-else><p class="muted">{{ outputItems.length }} hasil pada tahap ini.</p><div class="stage-list"><div v-for="(item,i) in outputItems" :key="i" class="stage-item"><strong>{{ item.question_number ? `Soal ${item.question_number}` : `Hasil ${i+1}` }}</strong><span v-if="item.mentor_view?.final_score != null || item.normalized_score != null || item.final_score != null"> · Nilai {{ item.mentor_view?.final_score ?? item.normalized_score ?? item.final_score }}</span><p v-if="item.question"><b>Soal:</b> {{ readableAnswer(item.question) }}</p><p v-if="item.answer || item.student_answer"><b>Jawaban:</b> {{ readableAnswer(item.answer || item.student_answer) }}</p><p v-if="item.answer_status">Status jawaban: {{ item.answer_status }}</p><p v-if="item.language || item.subject || item.question_type">{{ item.language || '—' }} · {{ item.subject || '—' }} · {{ item.question_type || '—' }} · Confidence {{ item.confidence ?? '—' }}</p><p v-if="item.evaluation_strategy">Strategi: {{ item.evaluation_strategy }}</p><p v-if="item.feedback"><b>Feedback AI:</b> {{ item.feedback }}</p><p v-if="item.strengths?.length">Kelebihan: {{ item.strengths.join(' · ') }}</p><p v-if="item.weaknesses?.length">Perlu diperbaiki: {{ item.weaknesses.join(' · ') }}</p><p v-for="(criterion,ci) in item.criteria_scores || []" :key="ci">{{ criterion.name }}: {{ criterion.score }}</p><details><summary>Data lengkap</summary><pre>{{ JSON.stringify(item,null,2) }}</pre></details></div></div><p v-if="!outputItems.length" class="muted">Tidak ada butir hasil pada tahap ini.</p></template>
      </div><p v-else class="muted">Tahap ini belum menghasilkan output.</p>
    </details>
  </div>
</section><section v-else class="panel ai-section"><h2>Pemeriksaan otomatis</h2><p class="muted">Tipe {{ bank?.assessment_type?.replaceAll('_',' ') }} diperiksa oleh aturan task bank. Bantuan AI tidak diperlukan.</p></section></AssessmentLayout>
